// ─── How good is the Arabic on the resource pages? ──────────────────────────
//
// Twenty-one resource pages carry a sibling content.ts of { en, ar } pairs,
// generated by a local Ollama run (qwen2.5:14b, gemma4:26b fallback) according
// to each file's own header. Nothing has ever checked the output.
//
// Reading three of them while fixing EXAM-3 turned up, in a single file:
//
//   s15  "Key difference from Q3:"  ->  "différence الرئيسية من السؤال الثالث:"
//   s28  "Support each point with evidence from"  ->  "أدعم كل نقطة bằng أدلة من"
//   s46  "Example paragraph:"  ->  a paragraph about "روميو وكايلا" (Romeo and
//        Kayla), inviting the reader to analyse a scene with Juliet
//   s44  "Example Responses"  ->  120 words about Hamlet, cut off mid-word
//
// A French word, a Vietnamese word, and two answers that are not translations
// of anything. This script counts the shapes those take, so the scale is a
// number rather than an impression.
//
//   node scripts/audit-machine-translated-content.mjs [--samples]
//
// WHAT IT CANNOT DO is judge whether fluent Arabic says the right thing. Every
// heuristic here is a lower bound, and a clean file is not a verified file.

import { readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const ENTRY = /(\w+):\s*\{\s*en:\s*`((?:[^`\\]|\\.)*)`\s*,\s*ar:\s*`((?:[^`\\]|\\.)*)`\s*,?\s*\}/gs

/**
 * Latin text that belongs in Arabic copy: assessment-objective codes, exam
 * boards, qualification names, the brand. Anything else in Latin script is a
 * word the translator failed to translate.
 */
const ALLOWED_LATIN =
  /^(AO[1-6]|GCSE|IGCSE|IELTS|AQA|OCR|Edexcel|Eduqas|Pearson|Cambridge|CAIE|English|Hub|The|A|B|C|Level|Paper|Section|KS[0-9]|[0-9A-Z]{2,7}[0-9/]*)$/i

function walk(dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name)
    if (entry.isDirectory()) walk(full, out)
    else if (entry.name === 'content.ts') out.push(full)
  }
  return out
}

const files = walk('src/app')
const findings = { empty: [], latin: [], bloated: [], truncated: [], identical: [] }
let total = 0

for (const file of files) {
  const source = readFileSync(file, 'utf8')
  if (!/export const STRINGS/.test(source)) continue
  const short = file.split(/[\\/]/).slice(-2).join('/')

  for (const m of source.matchAll(ENTRY)) {
    const [, key, en, ar] = m
    total += 1
    const where = `${short} ${key}`

    if (!ar.trim()) {
      findings.empty.push({ where, en })
      continue
    }
    if (ar.trim() === en.trim()) {
      findings.identical.push({ where, en })
      continue
    }

    // Latin words left inside the Arabic.
    const latin = (ar.match(/[A-Za-zÀ-ÿ]+/g) ?? []).filter((w) => !ALLOWED_LATIN.test(w))
    if (latin.length) findings.latin.push({ where, en, ar, latin: [...new Set(latin)] })

    // Arabic is usually SHORTER than English in characters. Three times the
    // length means the model wrote an essay instead of a translation.
    if (en.length > 8 && ar.length > en.length * 3) {
      findings.bloated.push({ where, en, ar, ratio: (ar.length / en.length).toFixed(1) })
    }

    // Cut off mid-sentence: no terminal punctuation and long enough that the
    // absence is meaningful.
    if (ar.length > 60 && !/[.!؟?:»"”)\]]\s*$/.test(ar.trim())) {
      findings.truncated.push({ where, en, ar })
    }
  }
}

const label = {
  empty: 'no Arabic at all (falls back to English, so harmless but untranslated)',
  identical: 'Arabic identical to the English',
  latin: 'untranslated Latin words spliced into the Arabic',
  bloated: 'Arabic more than 3x the English length, so not a translation',
  truncated: 'Arabic ends mid-sentence',
}

console.log(`${total} translated strings across ${files.length} content files.\n`)
for (const [kind, rows] of Object.entries(findings)) {
  console.log(`${String(rows.length).padStart(4)}  ${label[kind]}`)
}

if (process.argv.includes('--samples')) {
  for (const [kind, rows] of Object.entries(findings)) {
    if (!rows.length) continue
    console.log(`\n── ${label[kind]} ──`)
    for (const row of rows.slice(0, 8)) {
      console.log(`  ${row.where}`)
      console.log(`    en: ${row.en.slice(0, 80)}`)
      if (row.ar !== undefined) console.log(`    ar: ${row.ar.slice(0, 80).replace(/\n/g, ' ')}`)
      if (row.latin) console.log(`    latin: ${row.latin.join(', ')}`)
    }
    if (rows.length > 8) console.log(`  ... and ${rows.length - 8} more`)
  }
}
